| `COMP_STICKY_STRUCTURE` | warn | template/style | `position\\s*:?\\s*sticky\|sticky-section\|sticky-header` | WebView `position: sticky` 需与 Skyline sticky 组件分支隔离；`sticky-header` 需首子节点且显式背景色                      | Skyline 分支使用 `scroll-view` + `sticky-section` / `sticky-header`，WebView 分支保留 CSS sticky                                                    | 无吸顶需求或 WebView-only | [sticky 适配](skyline-style-practice.md#sticky-吸顶替代方案) |
| `COMP_PICKER_VIEW_INDICATOR` | warn | template | `picker-view[\s\S]*(indicator-class\|mask-style\|indicator-style)` | `indicator-style` 仅支持 `height` / `border` / `background-color`；`indicator-class` / `mask-style` 暂未支持 | 只保留支持的 `indicator-style` 子属性                                                                                                               | 已回源确认 | [高频差异](skyline-template-reference.md#skyline-相对-webview-的高频差异补充) |
## Skyline 相对 WebView 的高频差异补充

| 组件 | 差异                                                                                                                                                                       |
| --- |--------------------------------------------------------------------------------------------------------------------------------------------------------------------------|
| `picker-view` | `indicator-style` 仅支持 `height` / `border` / `background-color`；`indicator-class` / `mask-style` 暂未支持；Skyline 默认存在上下边框，无自定义边框需设置 `indicator-style="border: none;"` 去除默认边框 |
| `swiper` | `layout-type="stackLeft"` / `stackRight` / `tinder` 时仅支持 `indicator-type="normal"`                                                                                       |
| `swiper` | `indicator-type="scrollFixedCenter"` / `swap` / `swapYRotation` 时不支持 `circular`                                                                                          |
| `swiper` | `previous-margin` / `display-multiple-items` / `vertical` 的布局计算与 WebView 不一致；设置 `next-margin > 0` 时对齐 WebView 实现                                                         |
| `input` / `textarea` | 原生组件字体固定为系统字体，`font-family` 不生效；聚焦期间避免 CSS 动画                                                                                                                            |
| `video` | 全屏已支持，投屏暂未支持；开发者工具暂未支持调试，需真机预览                                                                                                                                           |
| `map` / `canvas` / `camera` | 开发者工具暂未支持调试，需真机预览                                                                                                                                                        |
| `rich-text` | 默认渲染模式不保证与 WebView 完全一致；`mode="web"` 时对齐 WebView                                                                                                                         |
| `scroll-view` | 滚动 `scroll-view` 会阻止页面回弹，无法触发页面级 `onPullDownRefresh`                                                                                                                     |
| `scroll-view` | `scroll-into-view` 优先级高于 `scroll-top`；目标 id 不能以数字开头                                                                                                                      |
| `scroll-view` | 自定义下拉刷新节点必须声明 `slot="refresher"`                                                                                                                                         |
| `scroll-view` | 滚动条长度为预估值；直接子节点高度差异较大时，滚动条长度不保证精确                                                                                                                                        |
| `scroll-view` | 横向滚动需同时开启 `enable-flex`，并设置横向布局样式（如 `flex-direction: row`）以兼容 WebView                                                                                                    |
| `scroll-view` | `type="list"` 下列表项可加 `list-item` 启用样式共享优化；列表项仍必须是直接子节点                                                                                                                   |
| `scroll-view` | 基础库 2.4.0 以下不支持嵌套 `textarea` / `map` / `canvas` / `video`                                                                                                                |
| `text` | `user-select` 会使节点变为 `inline-block`；除文本节点外，其他节点无法长按选中                                                                                                                    |
| `span` | 用于图文内联混排，仅微信支持，跨平台建议按 `<view mpxTagName@wx="span"></view>`                                                                                                               |
| `input` / `textarea` | `bindkeyboardheightchange` 存在多次触发场景，应忽略相同高度值避免重复布局                                                                                                                       |
| `sticky-section` / `sticky-header` | WebView 常用的 CSS `position: sticky` 在 Skyline 下应替换为 `scroll-view type="custom"` + `sticky-section` / `sticky-header`                                                      |

#!/usr/bin/env node
'use strict'

const fs = require('fs')
const path = require('path')
const os = require('os')
const crypto = require('crypto')

class MpxCliNotFoundError extends Error {
  constructor (msg) { super(msg); this.name = 'MpxCliNotFoundError' }
}
class InvalidInputError extends Error {
  constructor (msg) { super(msg); this.name = 'InvalidInputError' }
}

function resolveProjectRoot (startPath) {
  let cur = fs.existsSync(startPath) && fs.statSync(startPath).isDirectory()
    ? startPath
    : path.dirname(startPath)
  cur = path.resolve(cur)
  const rootDir = path.parse(cur).root
  while (true) {
    const pkgPath = path.join(cur, 'package.json')
    if (fs.existsSync(pkgPath)) {
      try {
        const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'))
        const deps = Object.assign({}, pkg.dependencies, pkg.devDependencies)
        if (deps['@mpxjs/mpx-cli-service']) return cur
      } catch (_) { /* ignore parse error */ }
    }
    if (fs.existsSync(path.join(cur, 'node_modules', '@mpxjs', 'mpx-cli-service'))) {
      return cur
    }
    if (cur === rootDir) return null
    cur = path.dirname(cur)
  }
}

function requireFromProject (name, projectRoot) {
  const resolved = require.resolve(name, { paths: [projectRoot] })
  return require(resolved)
}

// 简单 semver 比较：a >= b 返回 true。仅支持 'x.y.z' 三段数字。
function gteVersion (a, b) {
  const pa = String(a).split('.').map(n => parseInt(n, 10) || 0)
  const pb = String(b).split('.').map(n => parseInt(n, 10) || 0)
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const da = pa[i] || 0
    const db = pb[i] || 0
    if (da > db) return true
    if (da < db) return false
  }
  return true
}

// `partialCompileRules.components` 自 @mpxjs/webpack-plugin@2.10.20 起支持。
// 低版本回退到前置 loader 剥离 usingComponents 的"不完美"兼容方案。
const PARTIAL_COMPILE_COMPONENTS_MIN_VERSION = '2.10.20'

async function compileValidate (input, options = {}) {
  const mpxPaths = (Array.isArray(input) ? input : [input]).map(p => path.resolve(p))
  for (const p of mpxPaths) {
    if (!fs.existsSync(p) || !fs.statSync(p).isFile()) {
      throw new InvalidInputError(`输入不是有效文件: ${p}`)
    }
  }

  const {
    target = 'ios',
    type = 'component',
    projectRoot: explicitRoot,
    ignoreSubComponents = true,
    cleanup = true
  } = options

  if (type !== 'page' && type !== 'component') {
    throw new InvalidInputError(`不支持的 type: ${type}，只接受 'page' 或 'component'`)
  }

  const projectRoot = explicitRoot
    ? path.resolve(explicitRoot)
    : resolveProjectRoot(mpxPaths[0])
  if (!projectRoot) {
    throw new MpxCliNotFoundError(
      `当前环境未安装 mpx-cli (@mpxjs/mpx-cli-service)，无法执行真实编译校验。起点: ${mpxPaths[0]}`
    )
  }
  try {
    require.resolve('@mpxjs/mpx-cli-service', { paths: [projectRoot] })
  } catch (_) {
    throw new MpxCliNotFoundError(`项目 ${projectRoot} 中未安装 @mpxjs/mpx-cli-service`)
  }

  const targets = Array.isArray(target) ? target : [target]
  if (targets.length === 1) {
    return compileOne(projectRoot, mpxPaths, targets[0], type, ignoreSubComponents, cleanup)
  }
  const out = {}
  for (const t of targets) {
    out[t] = await compileOne(projectRoot, mpxPaths, t, type, ignoreSubComponents, cleanup)
  }
  return out
